const j = $input.first().json;
if (j.error) return [{ json: j }];
const insightsAcc = j.insightsAccount;
const insightsAd = j.insightsAds || [];
const spend = parseFloat(insightsAcc?.spend || 0) || 0;
const impr = parseInt(insightsAcc?.impressions || 0, 10) || 0;
const clicks = parseInt(insightsAcc?.clicks || 0, 10) || 0;
const ctr = insightsAcc?.ctr || '0';
let leads = 0;
const actions = insightsAcc?.actions || [];
for (const a of actions) {
  if (a.action_type === 'lead') { leads = parseInt(a.value || 0, 10) || 0; break; }
}
const cpl = leads > 0 ? (spend / leads).toFixed(0) : null;
const rows = insightsAd.map(d => {
  const s = parseFloat(d.spend || 0) || 0;
  let l = 0;
  for (const a of (d.actions || [])) {
    if (a.action_type === 'lead') { l = parseInt(a.value || 0, 10) || 0; break; }
  }
  const cplAd = l > 0 ? s / l : 999999;
  return { ad_id: d.ad_id, ad_name: (d.ad_name || '').slice(0, 50), spend: s, leads: l, cpl: cplAd };
});
rows.sort((a, b) => a.cpl - b.cpl);
const ganadores = rows.filter(r => r.leads > 0).slice(0, 5);
let perdedores = rows.filter(r => r.spend > 0 && r.leads === 0).slice(0, 3);
if (rows.length && perdedores.length === 0) perdedores = rows.filter(r => r.leads > 0).slice(-2);
const period = j.date_preset || 'last_7d';
return [{ json: { ...j, metrics: { spend, impressions: impr, clicks, ctr, leads, cpl }, ganadores, perdedores, period } }];

const j = $input.first().json;
if (j.error) return [{ json: j }];
const g = (j.ganadores || []).map(x => x.ad_name + ' (CPL ' + (x.cpl?.toFixed?.(0) || x.cpl) + ')').join(', ');
const p = (j.perdedores || []).map(x => x.ad_name).join(', ');
const hist = (j.historial_reportes || []);
const textoHist = hist.length ? hist.slice(0, 5).map((r, i) => `Reporte ${i+1} (${r.period || 'N/A'}): ${(r.resumen_ia || '').slice(0, 200)}${(r.resumen_ia || '').length > 200 ? '...' : ''}`).join('\n') : 'Sin reportes anteriores.';
const prompt = `Eres un analista de Meta Ads. Usa el contexto de estrategia y el historial de reportes para dar una interpretación útil.

CONTEXTO DE ESTRATEGIA (último snapshot):
${j.strategy || 'No definida'}

HISTORIAL DE REPORTES RECIENTES (qué se ha analizado antes):
${textoHist}

MÉTRICAS ACTUALES (${j.period}): Gasto ${j.metrics?.spend} | Leads ${j.metrics?.leads} | CPL ${j.metrics?.cpl || 'N/A'}.
Ganadores (mantener): ${g || 'Ninguno'}.
Perdedores (revisar): ${p || 'Ninguno'}.

En 2-4 frases: ¿Los resultados van alineados con la estrategia? ¿Mejora o empeora respecto a lo visto antes? ¿Qué riesgo ves y una recomendación prioritaria? Sé directo.`;
return [{ json: { ...j, prompt_interpretacion: prompt } }];

const base = $('Ganadores y perdedores').first().json;
const out = $input.first().json;
if (base.error) return [{ json: base }];
const text = out?.response?.text ?? out?.text ?? out?.output ?? '';
return [{ json: { ...base, interpretacion_estrategica: text } }];
